<?php
declare(strict_types=1);
namespace App\Application;
use App\Domain\Offer\DocumentTaxCalculator;
use App\Domain\Offer\OfferCalculator;
use App\Domain\Offer\OfferValidator;
use App\Infrastructure\Pdf\PdfNumberFormatter;
use App\Infrastructure\Pdf\SimplePdf;
use App\Infrastructure\Persistence\DocumentSettingsRepository;
use PDO;
use RuntimeException;

final readonly class OfferPdfService
{
 public function __construct(private PDO $pdo,private DocumentSettingsRepository $settings,private OfferValidator $validator,private OfferCalculator $calculator){}
 /** @param array<string,mixed> $offer */
 public function render(array $offer):string
 {
  $this->validator->validate($offer);$offer=$this->calculator->calculate($offer);$project=$this->project((string)$offer['projectId']);$settings=$this->settings->get();
  $pdf=new SimplePdf();$numbers=new PdfNumberFormatter();$accent=$this->color((string)($settings['accentColor']??'#155a8a'));$left=(float)($settings['marginLeft']??45);$right=595-(float)($settings['marginRight']??45);$top=842-(float)($settings['marginTop']??42)-25;$bottom=(float)($settings['marginBottom']??82);$font=(float)($settings['baseFontSize']??8);
  $footer=function()use($pdf,$settings,$left,$right):void{if(!($settings['showFooter']??true))return;$pdf->line($left,72,$right,72);$columns=[[$this->company($settings),trim(($settings['street']??'').' '.($settings['houseNumber']??'')),trim(($settings['postalCode']??'').' '.($settings['city']??''))],array_filter([(string)($settings['phone']??'')!==''?'Telefon '.$settings['phone']:'',(string)($settings['email']??''),(string)($settings['website']??'')]),array_filter([(string)($settings['taxNumber']??'')!==''?'Steuernummer '.$settings['taxNumber']:'',(string)($settings['vatId']??'')!==''?'USt-ID '.$settings['vatId']:'']),array_filter([(string)($settings['bankName']??''),(string)($settings['iban']??'')!==''?'IBAN '.$settings['iban']:'',(string)($settings['bic']??'')!==''?'BIC '.$settings['bic']:''])];$width=($right-$left)/4;foreach($columns as $index=>$lines){$fy=58;foreach(array_filter($lines,static fn($v)=>trim((string)$v)!=='') as $line){$pdf->text($left+$index*$width,$fy,6.5,(string)$line,$fy===58);$fy-=10;}}if(trim((string)($settings['footerText']??''))!=='')$pdf->text($left,18,6.5,(string)$settings['footerText']);};
  $newPage=function(bool $first=false)use($pdf,$footer,$settings,$left,$right,$accent):void{if(!$first)$pdf->page();$footer();if($settings['showHeader']??true){$company=$this->company($settings);$pdf->text($left,800,14,$company?:'Calight',true,$accent);$this->logo($pdf,$settings,$left,$right);}};$newPage(true);
  $company=$this->company($settings);$addressY=($settings['addressMode']??'standard')==='window'?690:680;$sender=implode(' · ',array_filter([$company,trim(($settings['street']??'').' '.($settings['houseNumber']??'')),trim(($settings['postalCode']??'').' '.($settings['city']??''))]));$pdf->text($left,$addressY+18,6.5,$sender,false,'.35 .4 .45');$pdf->line($left,$addressY+12,$left+270,$addressY+12);$recipient=(string)($project['customer_display']??'');$pdf->text($left,$addressY-7,10,$recipient?:'Kein Kunde zugeordnet',true);$pdf->text($left,$addressY-22,9,trim(($project['customer_street']??'').' '.($project['customer_house_number']??'')));$pdf->text($left,$addressY-36,9,trim(($project['customer_postal_code']??'').' '.($project['customer_city']??'')));
  if($settings['showProjectInfo']??true){$meta=[['Belegnummer','folgt bei verbindlicher Ausgabe'],['Datum',date('d.m.Y')],['Projekt',(string)($project['project_number']??'')],['Objekt',(string)($project['name']??'')]];$my=$addressY-7;foreach($meta as [$label,$value]){if(trim($value)==='')continue;$pdf->text($right-200,$my,$font,$label,false,'.35 .4 .45');$pdf->text($right-115,$my,$font,$value,true);$my-=15;}}
  $pdf->text($left,535,17,'Angebot – Entwurf',true,$accent);$pdf->text($left,514,11,(string)$offer['title'],true);$y=480;foreach($this->wrap((string)($settings['introText']??''),105) as $line){$pdf->text($left,$y,$font+1,$line);$y-=12;}$y-=8;
  $tableHeader=function()use($pdf,&$y,$left,$right,$font):void{$pdf->text($left,$y,$font,'Pos.',true);$pdf->text($left+45,$y,$font,'Bezeichnung',true);$pdf->textRight($right-150,$y,$font,'Menge',true);$pdf->textRight($right-88,$y,$font,'Einzelpreis',true);$pdf->textRight($right,$y,$font,'Gesamt',true);$y-=9;$pdf->line($left,$y,$right,$y,'0.3 0.35 0.4');$y-=14;};$tableHeader();
  $ensure=function(float $height)use($newPage,$tableHeader,&$y,$top,$bottom):void{if($y-$height>=$bottom)return;$newPage();$y=$top;$tableHeader();};$hasSpecial=false;
  foreach($this->rows($offer['nodes'],[],(bool)($settings['showEmptyTitles']??false)) as $row){
   if($row['kind']==='title'){$lines=$this->wrap($row['text'],75);$description=$this->wrap($row['description'],90);$ensure(25+(count($lines)+count($description))*10);$pdf->text($left+4,$y,$font+1,$row['number'],true);foreach($lines as $line){$pdf->text($left+45+min($row['depth'],3)*7,$y,$font+1,$line,true);$y-=10;}foreach($description as $line){$pdf->text($left+52+min($row['depth'],3)*7,$y,$font-.5,$line,false,'.35 .4 .45');$y-=10;}$pdf->line($left,$y,$right,$y);$y-=13;continue;}
   if($row['kind']==='subtotal'){$ensure(24);$pdf->text($left+65,$y,$font,'Summe '.$row['label'],true);$pdf->textRight($right,$y,$font,$numbers->money($row['total']),true);$y-=8;$pdf->line($left+45,$y,$right,$y);$y-=15;continue;}
   $hasSpecial=$hasSpecial||$row['special'];$short=$this->wrap($row['text'],61);$description=$this->wrap($row['longText'],86);$ensure(min(55,25+(count($short)+min(2,count($description)))*10));$baseline=$y;$pdf->text($left+4,$y,$font,$row['number']);$badge=$row['positionType']==='bedarf'?'[BEDARF] ':($row['positionType']==='alternative'?'[ALTERNATIVE] ':'');foreach($short as $index=>$line){$pdf->text($left+45+min($row['depth'],3)*7,$y,$font,($index===0?$badge:'').$line,true);$y-=10;}$pdf->textRight($right-150,$baseline,$font,$numbers->quantity($row['quantity']).' '.$row['unit']);$pdf->textRight($right-88,$baseline,$font,$numbers->money($row['unitPrice']));$pdf->textRight($right,$baseline,$font,$numbers->money($row['total']),true);$y-=3;foreach($description as $line){$ensure(15);$pdf->text($left+45+min($row['depth'],3)*7,$y,$font-.5,$line,false,'.35 .4 .45');$y-=10;}$pdf->line($left,$y,$right,$y);$y-=13;
  }
  if($hasSpecial){$ensure(30);foreach($this->wrap('Hinweis: Bedarfs- und Alternativpositionen sind nicht Bestandteil der regulären Angebots- und Titelsummen.',95) as $line){$pdf->text($left,$y,$font,$line,true,'.35 .4 .45');$y-=10;}$y-=7;}
  $tax=(new DocumentTaxCalculator())->calculate((string)($offer['calculation']['netTotal']??'0.00'),(string)($settings['taxMode']??'standard'),(string)($settings['vatRate']??'19.00'),(string)($settings['taxNote']??''));$ensure(100);$pdf->text($right-185,$y,$font+1,'Summe netto');$pdf->textRight($right,$y,$font+1,$numbers->money($tax['net']));$y-=18;if($tax['mode']==='standard'){$pdf->text($right-185,$y,$font+1,'Umsatzsteuer '.$numbers->percent($tax['rate']));$pdf->textRight($right,$y,$font+1,$numbers->money($tax['tax']));$y-=18;}$pdf->line($right-190,$y+8,$right,$y+8,'0.3 0.35 0.4');$pdf->text($right-185,$y,$font+3,'Gesamtbetrag',true);$pdf->textRight($right,$y,$font+3,$numbers->money($tax['gross']),true,$accent);$y-=27;if($tax['note']!=='')foreach($this->wrap($tax['note'],70) as $line){$pdf->text($right-260,$y,$font,$line);$y-=10;}
  foreach([(string)($settings['paymentTerms']??''),(string)($settings['closingText']??'')] as $block){$y-=7;foreach($this->wrap($block,105) as $line){$ensure(12);$pdf->text($left,$y,$font,$line);$y-=11;}}return $pdf->output();
 }
 /** @param list<array<string,mixed>> $nodes @param list<int> $prefix @return list<array<string,mixed>> */
 private function rows(array $nodes,array $prefix=[],bool $showEmpty=false):array{$rows=[];$title=0;$position=0;foreach($nodes as $node){if(($node['type']??'')==='title'){$path=[...$prefix,++$title];$has=$this->containsPosition($node['children']??[]);if($showEmpty||$has)$rows[]=['kind'=>'title','number'=>implode('.',$path),'text'=>(string)$node['name'],'description'=>(string)($node['description']??''),'depth'=>count($path)-1];$rows=[...$rows,...$this->rows($node['children']??[],$path,$showEmpty)];if($has&&(string)($node['calculation']['subtotal']??'0.00')!=='0.00')$rows[]=['kind'=>'subtotal','label'=>'Titel '.implode('.',$path).': '.$node['name'],'total'=>(string)$node['calculation']['subtotal']];continue;}$positionType=(string)($node['positionType']??'normal');$number=($prefix?implode('.',$prefix).'.':'').str_pad((string)++$position,2,'0',STR_PAD_LEFT);$rows[]=['kind'=>'position','number'=>$number,'text'=>(string)$node['shortText'],'longText'=>(string)($node['longText']??''),'depth'=>count($prefix),'quantity'=>(string)$node['quantity'],'unit'=>(string)$node['unit'],'unitPrice'=>(string)($node['calculation']['effectiveUnitPrice']??'0'),'total'=>(string)($node['calculation']['positionTotal']??'0'),'positionType'=>$positionType,'special'=>$positionType!=='normal'];}return $rows;}
 /** @param list<array<string,mixed>> $nodes */ private function containsPosition(array $nodes):bool{foreach($nodes as $node){if(($node['type']??'')==='position'||(($node['type']??'')==='title'&&$this->containsPosition($node['children']??[])))return true;}return false;}
 /** @return list<string> */ private function wrap(string $text,int $width):array{$text=trim($text);if($text==='')return[];$lines=[];foreach(preg_split('/\R/',$text)?:[] as $paragraph){if($paragraph===''){$lines[]='';continue;}foreach(explode("\n",wordwrap($paragraph,$width,"\n",true)) as $line)$lines[]=$line;}return $lines;}
 /** @param array<string,mixed> $settings */ private function logo(SimplePdf $pdf,array $settings,float $left,float $right):void{if(!is_string($settings['logoData']??null)||!str_starts_with($settings['logoData'],'data:image/jpeg;base64,'))return;$data=base64_decode(substr($settings['logoData'],23),true);$width=(float)($settings['logoWidth']??120);$x=($settings['logoPosition']??'right')==='left'?$left:$right-$width;if($data!==false)$pdf->jpeg($data,$x,750,$width,$width*.45);}
 /** @param array<string,mixed> $settings */ private function company(array $settings):string{return trim((string)($settings['companyName']??'').' '.(string)($settings['legalForm']??''));}
 /** @return array<string,mixed> */ private function project(string $id):array{$s=$this->pdo->prepare("SELECT p.*,CASE WHEN c.customer_type='company' THEN c.company_name ELSE trim(c.first_name||' '||c.last_name) END customer_display,c.street customer_street,c.house_number customer_house_number,c.postal_code customer_postal_code,c.city customer_city FROM projects p LEFT JOIN customers c ON c.id=p.customer_id WHERE p.id=:id");$s->execute(['id'=>$id]);$row=$s->fetch();if(!is_array($row))throw new RuntimeException('Projekt wurde nicht gefunden.');return $row;}
 private function color(string $hex):string{$hex=ltrim($hex,'#');if(!preg_match('/^[0-9a-fA-F]{6}$/',$hex))return'0.08 0.35 0.54';return implode(' ',array_map(static fn(string $part):string=>(string)round(hexdec($part)/255,3),str_split($hex,2)));}
}
